fn ref_marker(&mut self) -> SyntaxKind {
    self.s.eat_while(is_valid_in_label_literal);

    // Don't include the trailing characters likely to be part of text.
    while matches!(self.s.scout(-1), Some('.' | ':')) {
        self.s.uneat();
